function segment(value: string, fallback: string) {
  return (
    value
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .slice(0, 100)
      .replace(/^_+|_+$/g, "") || fallback
  );
}

/** Immutable upload name; callers retain unique object directories. */
export function storageFilename(name: string, type: string, extension?: string) {
  const basename = name.split(/[/\\]/).at(-1) ?? "";
  const suffix = /\.([a-z0-9]{1,16})$/i.exec(basename);
  const stem = suffix ? basename.slice(0, -suffix[0].length) : basename;
  const fields = stem
    .trim()
    .replace(/^-+|-+$/g, "")
    .split("-")
    .map((field) => segment(field, ""));
  const modifiers = fields.slice(2).filter((field) => field && field !== "original");
  const filename = [fields[0] || "asset", segment(type, "file"), ...modifiers]
    .join("-")
    .slice(0, 230)
    .replace(/[_-]+$/g, "");
  return `${filename}.${extension ?? suffix?.[1].toLowerCase() ?? "bin"}`;
}

import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

import {
  listAgentModels,
  modelCredentials,
  modelSelection,
  streamAgentModel,
} from "@/components/plugins/agents/server/models.server";
import type { AgentRuntime } from "@/components/plugins/agents/server/types";
import {
  AgentsError,
  type AgentModelSettings,
  type AgentsSettingsClient,
} from "@/components/plugins/agents/types";

export interface AgentStoredConnection extends AgentModelSettings {
  encryptedToken: string;
}
export interface AgentsConnectionStore {
  get(): Promise<AgentStoredConnection | null>;
  set(connection: AgentStoredConnection): Promise<void>;
  remove(): Promise<void>;
}
export interface AgentsConnectionOptions<Context> {
  store: AgentsConnectionStore;
  /** A stable, server-only 32-byte key, stored separately from the database. */
  encryptionKey: Uint8Array;
  /** Resolve fresh website-administrator authorization on every settings request. */
  authorize(context: Context): Promise<boolean>;
}

/** One connection per website database. Pass runtime to createAgentsService. */
export function createAgentsModelConnection<Context>(options: AgentsConnectionOptions<Context>) {
  if (options.encryptionKey.byteLength !== 32) throw new AgentsError("INVALID");
  const key = Buffer.from(options.encryptionKey);
  const aad = (value: AgentModelSettings) =>
    Buffer.from(`agents:v1:${value.provider}:${value.model}`);
  function encrypt(token: string, selection: AgentModelSettings) {
    const iv = randomBytes(12);
    const cipher = createCipheriv("aes-256-gcm", key, iv);
    cipher.setAAD(aad(selection));
    const bytes = Buffer.concat([cipher.update(token, "utf8"), cipher.final()]);
    return Buffer.concat([iv, cipher.getAuthTag(), bytes]).toString("base64");
  }
  function decrypt(value: AgentStoredConnection) {
    const bytes = Buffer.from(value.encryptedToken, "base64");
    const decipher = createDecipheriv("aes-256-gcm", key, bytes.subarray(0, 12));
    decipher.setAAD(aad(value));
    decipher.setAuthTag(bytes.subarray(12, 28));
    return Buffer.concat([decipher.update(bytes.subarray(28)), decipher.final()]).toString("utf8");
  }
  async function credentials(input: { provider: AgentModelSettings["provider"]; token?: string }) {
    if (input.token) return input.token;
    const saved = await options.store.get();
    if (!saved || saved.provider !== input.provider) throw new AgentsError("INVALID");
    return decrypt(saved);
  }
  async function admin<T>(context: Context, action: () => Promise<T>): Promise<T> {
    try {
      if (!(await options.authorize(context))) throw new AgentsError("FORBIDDEN");
      return await action();
    } catch (error) {
      throw error instanceof AgentsError ? error : new AgentsError("RUNTIME");
    }
  }
  const runtime: AgentRuntime = {
    async *stream(input) {
      try {
        const saved = await options.store.get();
        if (!saved) throw new AgentsError("NOT_CONFIGURED");
        const connection = modelSelection.parse({ ...saved, token: decrypt(saved) });
        if (!connection.token) throw new AgentsError("NOT_CONFIGURED");
        yield* streamAgentModel({ ...connection, token: connection.token }, input);
      } catch (error) {
        throw error instanceof AgentsError ? error : new AgentsError("RUNTIME");
      }
    },
  };
  return {
    runtime,
    client(context: Context): AgentsSettingsClient {
      return {
        get: () =>
          admin(context, async () => {
            const saved = await options.store.get();
            return saved ? { provider: saved.provider, model: saved.model } : null;
          }),
        models: (raw) =>
          admin(context, async () => {
            const parsed = modelCredentials.safeParse(raw);
            if (!parsed.success) throw new AgentsError("INVALID");
            return listAgentModels(parsed.data.provider, await credentials(parsed.data));
          }),
        save: (raw) =>
          admin(context, async () => {
            const parsed = modelSelection.safeParse(raw);
            if (!parsed.success) throw new AgentsError("INVALID");
            const { provider, model } = parsed.data;
            const token = await credentials(parsed.data);
            const models = await listAgentModels(provider, token);
            if (!models.some((entry) => entry.id === model)) throw new AgentsError("INVALID");
            if (!(await options.authorize(context))) throw new AgentsError("FORBIDDEN");
            await options.store.set({
              provider,
              model,
              encryptedToken: encrypt(token, { provider, model }),
            });
          }),
        remove: () => admin(context, () => options.store.remove()),
      };
    },
  };
}

import { z } from "zod";

import type { AgentRuntime } from "@/components/plugins/agents/server/types";
import { AgentsError, type AgentModelProvider } from "@/components/plugins/agents/types";

const origins = {
  openai: "https://api.openai.com/v1",
  anthropic: "https://api.anthropic.com/v1",
  deepseek: "https://api.deepseek.com",
};
export const modelCredentials = z.object({
  provider: z.enum(["openai", "anthropic", "deepseek"]),
  token: z.string().trim().min(1).max(4096).regex(/^\S+$/).optional(),
});
export const modelSelection = modelCredentials.extend({
  model: z.string().trim().min(1).max(256).regex(/^\S+$/),
});
export type ModelConnection = z.infer<typeof modelSelection> & { token: string };

async function request(
  provider: AgentModelProvider,
  token: string,
  path: string,
  signal: AbortSignal,
  body?: unknown,
) {
  const response = await fetch(`${origins[provider]}${path}`, {
    method: body ? "POST" : "GET",
    redirect: "error",
    signal,
    headers: {
      "Content-Type": "application/json",
      ...(provider === "anthropic"
        ? { "x-api-key": token, "anthropic-version": "2023-06-01" }
        : { Authorization: `Bearer ${token}` }),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!response.ok) {
    await response.body?.cancel();
    throw new AgentsError("RUNTIME");
  }
  return response;
}

const modelList = z.object({
  data: z.array(z.object({ id: z.string(), display_name: z.string().optional() })),
  has_more: z.boolean().optional(),
  last_id: z.string().nullable().optional(),
});
export async function listAgentModels(provider: AgentModelProvider, token: string) {
  const signal = AbortSignal.timeout(15000);
  const models = [];
  let after = "";
  for (let page = 0; page < 20; page++) {
    const path =
      provider === "anthropic"
        ? `/models?limit=100${after ? `&after_id=${encodeURIComponent(after)}` : ""}`
        : "/models";
    const result = modelList.parse(await (await request(provider, token, path, signal)).json());
    models.push(
      ...result.data.map((model) => ({ id: model.id, label: model.display_name ?? model.id })),
    );
    if (!result.has_more) return models.sort((a, b) => a.label.localeCompare(b.label));
    if (!result.last_id || result.last_id === after) throw new AgentsError("RUNTIME");
    after = result.last_id;
  }
  throw new AgentsError("LIMIT");
}

// Provider events may split UTF-8 characters and SSE lines across network chunks.
async function* events(response: Response) {
  if (!response.body) throw new AgentsError("RUNTIME");
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let data: string[] = [];
  let eventSize = 0;
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      if (buffer.length + eventSize > 1024 * 1024) throw new AgentsError("LIMIT");
      let end;
      while ((end = buffer.indexOf("\n")) !== -1) {
        const line = buffer.slice(0, end).replace(/\r$/, "");
        buffer = buffer.slice(end + 1);
        if (!line) {
          if (data.length) {
            const payload = data.join("\n");
            data = [];
            eventSize = 0;
            if (payload === "[DONE]") return;
            yield JSON.parse(payload) as unknown;
          }
        } else if (line.startsWith("data:")) {
          const part = line.slice(5).replace(/^ /, "");
          data.push(part);
          eventSize += part.length;
        }
      }
    }
    if (buffer.trim() || data.length) throw new AgentsError("RUNTIME");
  } finally {
    await reader.cancel();
    reader.releaseLock();
  }
}

const completion = z.object({
  choices: z.array(
    z.object({
      finish_reason: z.string().nullable().optional(),
      delta: z.object({
        content: z.string().nullable().optional(),
        tool_calls: z
          .array(
            z.object({
              index: z.number().int(),
              id: z.string().optional(),
              function: z
                .object({ name: z.string().optional(), arguments: z.string().optional() })
                .optional(),
            }),
          )
          .optional(),
      }),
    }),
  ),
});
const anthropicEvent = z.object({
  type: z.string(),
  index: z.number().int().optional(),
  content_block: z
    .object({ type: z.string(), id: z.string().optional(), name: z.string().optional() })
    .optional(),
  delta: z
    .object({
      text: z.string().optional(),
      partial_json: z.string().optional(),
      stop_reason: z.string().nullable().optional(),
    })
    .optional(),
});

export async function* streamAgentModel(
  connection: ModelConnection,
  input: Parameters<AgentRuntime["stream"]>[0],
): ReturnType<AgentRuntime["stream"]> {
  const { provider, model, token } = connection;
  const claude = provider === "anthropic";
  const signal = AbortSignal.any([input.signal, AbortSignal.timeout(90000)]);
  const messages: unknown[] = [];
  for (const entry of input.messages) {
    if (entry.role === "tool" && entry.tool) {
      const { callId, name, input: args } = entry.tool;
      messages.push(
        ...(claude
          ? [
              { role: "assistant", content: [{ type: "tool_use", id: callId, name, input: args }] },
              {
                role: "user",
                content: [{ type: "tool_result", tool_use_id: callId, content: entry.text }],
              },
            ]
          : [
              {
                role: "assistant",
                content: null,
                tool_calls: [
                  {
                    id: callId,
                    type: "function",
                    function: { name, arguments: JSON.stringify(args) },
                  },
                ],
              },
              { role: "tool", tool_call_id: callId, content: entry.text },
            ]),
      );
    } else {
      messages.push({
        role: entry.role === "assistant" ? "assistant" : "user",
        content:
          entry.text +
          (entry.attachments.length ? `\nAttachments: ${JSON.stringify(entry.attachments)}` : ""),
      });
    }
  }
  const tools = input.tools.map((tool) =>
    claude
      ? { name: tool.name, description: tool.description, input_schema: tool.inputSchema }
      : {
          type: "function",
          function: {
            name: tool.name,
            description: tool.description,
            parameters: tool.inputSchema,
            strict: false,
          },
        },
  );
  const body = {
    model,
    stream: true,
    messages: claude ? messages : [{ role: "system", content: input.instructions }, ...messages],
    ...(claude
      ? { system: input.instructions, max_tokens: 4096 }
      : provider === "deepseek"
        ? { max_tokens: 4096 }
        : { max_completion_tokens: 4096 }),
    ...(provider === "deepseek" ? { thinking: { type: "disabled" } } : {}),
    ...(tools.length
      ? {
          tools,
          ...(claude
            ? { tool_choice: { type: "auto", disable_parallel_tool_use: true } }
            : { parallel_tool_calls: false }),
        }
      : {}),
  };
  let call: { id: string; name: string; args: string; index: number } | null = null;
  let finished = false;
  let reason: string | null = null;
  try {
    const response = await request(
      provider,
      token,
      claude ? "/messages" : "/chat/completions",
      signal,
      body,
    );
    for await (const raw of events(response)) {
      signal.throwIfAborted();
      if (claude) {
        const event = anthropicEvent.parse(raw);
        if (event.type === "error") throw new AgentsError("RUNTIME");
        if (event.type === "content_block_start" && event.content_block?.type === "tool_use") {
          if (
            call ||
            !event.content_block.id ||
            !event.content_block.name ||
            event.index === undefined
          )
            throw new AgentsError("RUNTIME");
          call = {
            id: event.content_block.id,
            name: event.content_block.name,
            args: "",
            index: event.index,
          };
        }
        if (event.delta?.text) yield { type: "text", text: event.delta.text };
        if (event.delta?.partial_json) {
          if (!call || event.index !== call.index) throw new AgentsError("RUNTIME");
          call.args += event.delta.partial_json;
        }
        if (event.delta?.stop_reason) reason = event.delta.stop_reason;
        if (event.type === "message_stop") finished = true;
      } else {
        const event = completion.parse(raw);
        const choice = event.choices[0];
        if (choice?.delta.content) yield { type: "text", text: choice.delta.content };
        for (const tool of choice?.delta.tool_calls ?? []) {
          call ??= { id: "", name: "", args: "", index: tool.index };
          if (tool.index !== call.index) throw new AgentsError("RUNTIME");
          call.id += tool.id ?? "";
          call.name += tool.function?.name ?? "";
          call.args += tool.function?.arguments ?? "";
        }
        if (choice?.finish_reason) {
          reason = choice.finish_reason;
          finished = true;
        }
      }
      if (call && call.args.length > 1024 * 1024) throw new AgentsError("LIMIT");
    }
    if (!finished || !["stop", "end_turn", "tool_calls", "tool_use"].includes(reason ?? ""))
      throw new AgentsError("RUNTIME");
    if (call) {
      if (!call.id || !call.name || !["tool_calls", "tool_use"].includes(reason!))
        throw new AgentsError("RUNTIME");
      yield {
        type: "tool",
        callId: call.id,
        name: call.name,
        input: JSON.parse(call.args || "{}") as unknown,
      };
    }
  } catch {
    throw new AgentsError("RUNTIME");
  }
}

import { randomUUID } from "node:crypto";

import { z } from "zod";

import type {
  AgentFiles,
  AgentRecord,
  AgentServerOperation,
  AgentStoredAction,
  AgentTool,
} from "@/components/plugins/agents/server/types";
import {
  AgentsError,
  safeAgentResultHref,
  type AgentConversation,
  type AgentMessage,
} from "@/components/plugins/agents/types";

const id = z.string().min(1).max(250);
const decisionInput = z.object({ conversationId: id, actionId: id, approve: z.boolean() });
export function agentSnapshot(value: unknown): string {
  return (
    JSON.stringify(value, (_key, item: unknown) => {
      if (item && typeof item === "object" && !Array.isArray(item))
        return Object.fromEntries(Object.entries(item).sort(([a], [b]) => a.localeCompare(b)));
      return item;
    }) ?? "null"
  );
}
export function parse<T>(schema: z.ZodType<T>, input: unknown): T {
  const result = schema.safeParse(input);
  if (!result.success) throw new AgentsError("INVALID");
  return result.data;
}
export function toolResult(value: unknown): string {
  const text = JSON.stringify(value) ?? "null";
  return text.length > 128000
    ? `${text.slice(0, 128000)}\n[Result shortened; request a smaller selection.]`
    : text;
}

export function actionMessage(action: AgentStoredAction, text: string): AgentMessage {
  return {
    id: randomUUID(),
    role: "tool",
    text: `${action.tool}: ${text}`,
    attachments: [],
    tool: { callId: action.callId, name: action.tool, input: action.input },
  };
}

interface ExecutionOptions<Context> {
  access(
    this: void,
    context: Context,
    conversationId: string,
  ): Promise<{ ownerId: string; operation: AgentServerOperation<Context>; record: AgentRecord }>;
  change<T>(
    this: void,
    conversationId: string,
    ownerId: string,
    update: (record: AgentRecord) => T,
  ): Promise<T>;
  get(this: void, context: Context, conversationId: string): Promise<AgentConversation>;
  files(this: void, context: Context, conversationId: string): AgentFiles;
  resultHref?(
    context: Context,
    action: { operationId: string; tool: string; input: unknown; result: unknown },
  ): string | null | undefined;
}

/** Both chat and MCP cross this seam; only prepared, stored arguments can execute. */
export function createAgentExecutor<Context>(options: ExecutionOptions<Context>) {
  const { access, change, get, files } = options;
  async function read(context: Context, tool: AgentTool<Context>, raw: unknown, files: AgentFiles) {
    if (tool.kind !== "read") throw new AgentsError("INVALID");
    return tool.run(context, parse(tool.schema, raw), files);
  }
  async function prepare(
    context: Context,
    tool: AgentTool<Context>,
    raw: unknown,
    files: AgentFiles,
    messageId: string,
    callId: string,
  ): Promise<AgentStoredAction> {
    if (tool.kind !== "write") throw new AgentsError("INVALID");
    const input = parse(tool.schema, raw);
    const prepared = await tool.prepare(context, input, files);
    return {
      id: randomUUID(),
      callId,
      messageId,
      tool: tool.name,
      input,
      preview: prepared.preview,
      snapshot: agentSnapshot(prepared.snapshot),
      status: "pending",
    };
  }
  async function decide(context: Context, raw: unknown) {
    const input = parse(decisionInput, raw);
    const { ownerId, operation } = await access(context, input.conversationId);
    const runId = randomUUID();
    const action = await change(input.conversationId, ownerId, (record) => {
      const action = record.actions.find((candidate) => candidate.id === input.actionId);
      if (record.deleting) throw new AgentsError("NOT_FOUND");
      if (!action) throw new AgentsError("NOT_FOUND");
      if (action.status !== "pending") return null;
      if (record.run) throw new AgentsError("BUSY");
      if (!input.approve) {
        action.status = "rejected";
        record.messages.push(actionMessage(action, "User rejected this action."));
        record.canResume = true;
        return null;
      }
      action.status = "executing";
      record.run = { id: runId, startedAt: new Date().toISOString() };
      return structuredClone(action);
    });
    if (!action) return get(context, input.conversationId);
    const tool = operation.tools.find((tool) => tool.name === action.tool);
    let started = false;
    try {
      if (
        !tool ||
        tool.kind !== "write" ||
        (action.expiresAt && Date.parse(action.expiresAt) <= Date.now())
      )
        throw new AgentsError("STALE");
      const args = parse(tool.schema, action.input);
      const prepared = await tool.prepare(context, args, files(context, input.conversationId));
      if (
        agentSnapshot(prepared.snapshot) !== action.snapshot ||
        agentSnapshot(prepared.preview) !== agentSnapshot(action.preview)
      )
        throw new AgentsError("STALE");
      const current = await access(context, input.conversationId);
      if (current.record.run?.id !== runId) throw new AgentsError("BUSY");
      started = true;
      const result = await tool.run(
        context,
        args,
        files(context, input.conversationId),
        action.id,
        prepared.snapshot,
      );
      let resultHref: string | undefined;
      try {
        resultHref = safeAgentResultHref(
          options.resultHref?.(context, {
            operationId: operation.id,
            tool: tool.name,
            input: args,
            result,
          }),
        );
      } catch {
        // A navigation failure must not make a completed write retryable.
      }
      await change(input.conversationId, ownerId, (record) => {
        const saved = record.actions.find((candidate) => candidate.id === action.id)!;
        if (record.run?.id !== runId) {
          saved.status = "unresolved";
          saved.result =
            "A late execution completed after request recovery. Verify the plugin state again.";
          record.canResume = false;
          return;
        }
        saved.status = "succeeded";
        saved.result = toolResult(result);
        saved.resultHref = resultHref;
        record.messages.push(actionMessage(saved, saved.result));
        record.run = null;
        record.canResume = true;
      });
    } catch (error) {
      await change(input.conversationId, ownerId, (record) => {
        const saved = record.actions.find((candidate) => candidate.id === action.id)!;
        if (record.run?.id !== runId) {
          saved.status = "unresolved";
          record.canResume = false;
          return;
        }
        const uncertain = started;
        saved.status = uncertain ? "unresolved" : "stale";
        record.run = null;
        record.canResume = !uncertain;
        record.messages.push(
          actionMessage(
            action,
            uncertain
              ? "Outcome unknown. Reconcile in the host before continuing."
              : "Proposal expired, validation failed or access changed. Prepare a new proposal.",
          ),
        );
      });
      if (error instanceof AgentsError && error.code === "FORBIDDEN") throw error;
    }
    return get(context, input.conversationId);
  }
  return { read, prepare, decide };
}
